#!/usr/bin/env python3
import json, sys

SRC = "/root/.claude/projects/-home-user-BookMinder/a42b9c92-c0e6-588e-bc6f-3d5e4f37b895.jsonl"
OUT = "/tmp/claude-0/-home-user-BookMinder/a42b9c92-c0e6-588e-bc6f-3d5e4f37b895/scratchpad/filtered.txt"

def esc(s):
    return s.replace("\r", "")

out = []
n = 0
with open(SRC) as f:
    for lineno, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            e = json.loads(line)
        except Exception:
            continue
        t = e.get("type")
        if t not in ("user", "assistant"):
            continue
        if e.get("isSidechain"):
            tag = "SIDECHAIN-"
        else:
            tag = ""
        msg = e.get("message") or {}
        role = msg.get("role")
        ts = (e.get("timestamp") or "")[:19]
        content = msg.get("content")
        blocks = []
        if isinstance(content, str):
            blocks = [{"type": "text", "text": content}]
        elif isinstance(content, list):
            blocks = content
        parts = []
        for b in blocks:
            if not isinstance(b, dict):
                continue
            bt = b.get("type")
            if bt == "text":
                txt = b.get("text") or ""
                if txt.strip():
                    parts.append(esc(txt))
            elif bt == "thinking":
                continue
            elif bt == "tool_use":
                name = b.get("name")
                inp = b.get("input") or {}
                s = json.dumps(inp, ensure_ascii=False)
                if len(s) > 500:
                    s = s[:500] + " …[TRUNC]"
                parts.append(f"<<TOOL {name} {s}>>")
            elif bt == "tool_result":
                continue
        if not parts:
            continue
        n += 1
        origin = ""
        o = e.get("origin")
        if isinstance(o, dict):
            origin = o.get("kind") or ""
        out.append(f"\n===== [{lineno}] {tag}{role.upper()} {ts} {origin} =====\n" + "\n".join(parts))

with open(OUT, "w") as f:
    f.write("\n".join(out))
print("entries:", n, "chars:", sum(len(x) for x in out))

